    border-radius: 9999px;
    cursor: pointer;
    border: none;
    white-space: nowrap;
    transition: all 0.3s ease;
  }
  .btn-primary {
    background: var(--gradient);
    color: #ffffff;
    box-shadow: 0 10px 40px rgba(254,49,132,0.3);
  }
  .btn-primary:hover {
    transform: translateY(-2px);
    box-shadow: 0 15px 50px rgba(254,49,132,0.4);
  }
  .btn-secondary {
    background: transparent;
    color: #ffffff;
    border: 1px solid rgba(255,255,255,0.2);
  }
  .btn-secondary:hover {
    background: rgba(255,255,255,0.05);
    border-color: rgba(255,255,255,0.4);
  }
  .btn-sm { padding: 0.7rem 1.4rem; font-size: 14px; }
  .btn-card {
    width: 100%;
    margin-top: 1.5rem;
  }

  /* ===== HERO ===== */
  .hero {
    position: relative;
    min-height: 92vh;
    display: flex;
    align-items: center;
    background: var(--black);
    overflow: hidden;
  }
  .hero::before {
    content: "";
    position: absolute;
    inset: 0;
    background:
      radial-gradient(ellipse 80% 50% at 50% 0%, rgba(254,49,132,0.18) 0%, transparent 50%),
      radial-gradient(ellipse 60% 40% at 85% 25%, rgba(255,107,53,0.12) 0%, transparent 50%),
      radial-gradient(ellipse 50% 30% at 15% 85%, rgba(236,114,17,0.10) 0%, transparent 50%);
    pointer-events: none;
  }
  .hero::after {
    content: "";
    position: absolute;
    inset: 0;
    background-image:
      linear-gradient(rgba(255,255,255,0.03) 1px, transparent 1px),
      linear-gradient(90deg, rgba(255,255,255,0.03) 1px, transparent 1px);
    background-size: 60px 60px;
    opacity: 0.4;
    pointer-events: none;
  }
  .hero-content {
    position: relative;
    z-index: 2;
    max-width: 780px;
    margin: 0 auto;
    text-align: center;
    padding: 6rem 0;
  }
  .label {
    display: inline-block;
    font-size: 14px;
    font-weight: 600;
    letter-spacing: 0.1em;
    text-transform: uppercase;
    color: var(--pink);
    margin-bottom: 1.5rem;
  }
  .hero h1 {
    font-size: 72px;
    margin-bottom: 1.5rem;
  }
  .hero .subhead {
    font-size: 18px;
    color: rgba(255,255,255,0.6);
    max-width: 560px;
    margin: 0 auto 2.5rem;
  }
  .hero-actions {
    display: flex;
    justify-content: center;
    gap: 16px;
    flex-wrap: wrap;
  }

  /* ===== SECTION HEADERS ===== */
  section { padding: 8rem 0; position: relative; }
  .section-head {
    text-align: center;
    max-width: 640px;
    margin: 0 auto 4rem;
  }
  .section-head h2 { font-size: 42px; }

