    font-size: 11px;
    font-weight: 600;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: var(--pink);
    background: rgba(254,49,132,0.1);
    border: 1px solid rgba(254,49,132,0.2);
    border-radius: 9999px;
    padding: 5px 12px;
