    font-size: 12px;
    color: rgba(255,255,255,0.4);
    margin-top: 1rem;
  }
  .sample-note {
    text-align: center;
    font-size: 13px;
    color: rgba(255,255,255,0.4);
    margin-top: 3rem;
  }

