    justify-content: space-between;
    align-items: center;
    flex-wrap: wrap;
    gap: 20px;
  }
  .footer-links {
    display: flex;
    gap: 24px;
    list-style: none;
  }
  .footer-links a {
    color: rgba(255,255,255,0.5);
    font-size: 14px;
  }
  .footer-links a:hover { color: #ffffff; }
