    .nav .container { height: 64px; }
    .nav-actions .btn-secondary { display: none; }
    .hero { min-height: 88vh; }
    .hero-content { padding: 3.5rem 0; }
    .hero h1 { font-size: 40px; }
    .hero .subhead { font-size: 16px; }
    .hero-actions { flex-direction: column; width: 100%; }
    .hero-actions .btn { width: 100%; }

    .section-head h2 { font-size: 30px; }

    .acts-grid { grid-template-columns: 1fr; }
    .act-card { padding: 2rem 1.5rem; }
    .status-badge { position: static; display: inline-block; margin-bottom: 1rem; }
    .act-card h3 { padding-right: 0; }

    .steps-grid { grid-template-columns: 1fr; gap: 28px; }

    .final-cta h2 { font-size: 32px; }

    .footer-row { flex-direction: column; text-align: center; }
    .footer-links { flex-wrap: wrap; justify-content: center; }
  }
</style>
</head>
